          offset: { type: 'integer', default: 0, description: 'Number of results to skip (default 0).' },
          limit: { type: 'integer', default: 2, description: 'Max results per page (default 2, range 1-5).' }
        },
        required: ['query'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'catalog_search') {
    throw new Error('Unknown tool: ' + name);
  }

  // Validate arguments
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Arguments must be an object');
  }

  const extraKeys = Object.keys(args).filter(k => !['query','offset','limit'].includes(k));
  if (extraKeys.length > 0) {
    throw new Error('Unexpected arguments: ' + extraKeys.join(', '));
  }

  if (!('query' in args)) {
    throw new Error('Missing required argument: query');
  }

  const query = args.query;
  if (typeof query !== 'string') {
    throw new Error('query must be a string');
  }

  let offset = 0;
  if ('offset' in args) {
    offset = args.offset;
    if (!Number.isInteger(offset) || offset < 0) {
      throw new Error('offset must be a non-negative integer');
    }
  }

  let limit = 2;
  if ('limit' in args) {
    limit = args.limit;
    if (!Number.isInteger(limit) || limit < 1 || limit > 5) {
      throw new Error('limit must be an integer between 1 and 5');
    }
  }

  const q = query.toLowerCase();
  const matches = items.filter(it => it.name.toLowerCase().includes(q));
  const page = matches.slice(offset, offset + limit);
  const result = { results: page };
  if (offset + limit < matches.length) {
    result.next_offset = offset + limit;
  }

  return { content: [{ type: 'text', text: JSON.stringify(result) }] };
}
